package pe.vichaval.gestionriego.config;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.*;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.*;import pe.vichaval.gestionriego.usuario.entity.*;import pe.vichaval.gestionriego.usuario.enums.*;import pe.vichaval.gestionriego.usuario.repository.*;@Configuration public class InitialUserConfig{@Bean CommandLineRunner init(UsuarioRepository u,RolRepository r,PasswordEncoder e,@Value("${APP_ADMIN_PASSWORD:Admin123*}")String a,@Value("${APP_TESORERO_PASSWORD:Tesorero123*}")String t,@Value("${APP_OPERADOR_PASSWORD:Operador123*}")String o){return x->{add(u,r,e,"admin",a,CodigoRol.ADMINISTRADOR);add(u,r,e,"tesorero",t,CodigoRol.TESORERIA);add(u,r,e,"operador",o,CodigoRol.OPERADOR);};}void add(UsuarioRepository u,RolRepository r,PasswordEncoder e,String n,String p,CodigoRol c){if(!u.existsByUsernameIgnoreCase(n))u.save(new Usuario(n,e.encode(p),n,"Vichayal",r.findByCodigo(c).orElseThrow()));}}